package org.humanjourney.core.mapfeature;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.mockito.MockedStatic;
import net.minecraft.SharedConstants;
import net.minecraft.server.Bootstrap;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.server.players.PlayerList;
import net.minecraft.world.level.Level;
import net.minecraft.network.chat.Component;
import net.minecraft.commands.*;
import net.minecraftforge.event.RegisterCommandsEvent;
import com.mojang.brigadier.CommandDispatcher;
class FeatureServerTest {
 static MockedStatic<net.minecraftforge.fml.ModLoader> loader;
 @BeforeAll static void bootstrap(){loader=mockStatic(net.minecraftforge.fml.ModLoader.class);loader.when(net.minecraftforge.fml.ModLoader::get).thenReturn(mock(net.minecraftforge.fml.ModLoader.class));SharedConstants.tryDetectVersion();Bootstrap.bootStrap();}
 @AfterAll static void closeLoader(){loader.close();}
 MinecraftServer server;SavedFeatures saved;List<ServerPlayer> online;Map<UUID,Set<String>> tags;Map<UUID,Double> x;Map<UUID,List<FeaturePackets.Frame>> sent;AtomicInteger clock;MockedStatic<SavedFeatures> saves;MockedStatic<FeatureNetwork> network;
 @BeforeEach void setup(){FeatureServer.clear();FeatureCatalog.reset();FeatureCatalog.accept(FeatureModelTest.catalog(FeatureModelTest.polygon("sea",1),FeatureModelTest.line("river",1)));server=mock(MinecraftServer.class);var players=mock(PlayerList.class);online=new ArrayList<>();tags=new HashMap<>();x=new HashMap<>();sent=new HashMap<>();clock=new AtomicInteger(10);saved=new SavedFeatures();when(server.getPlayerList()).thenReturn(players);when(players.getPlayers()).thenAnswer(i->online);when(server.getTickCount()).thenAnswer(i->clock.get());saves=mockStatic(SavedFeatures.class,i->i.getMethod().getName().equals("get")?saved:i.callRealMethod());network=mockStatic(FeatureNetwork.class);network.when(()->FeatureNetwork.send(any(),any())).thenAnswer(i->{ServerPlayer p=i.getArgument(1);sent.get(p.getUUID()).add(i.getArgument(0));return true;});}
 @AfterEach void close(){network.close();saves.close();FeatureServer.clear();FeatureCatalog.reset();}
 ServerPlayer player(String name,String... role){var p=mock(ServerPlayer.class);var level=mock(ServerLevel.class);var id=UUID.nameUUIDFromBytes(name.getBytes(java.nio.charset.StandardCharsets.UTF_8));tags.put(id,new HashSet<>(List.of(role)));x.put(id,50D);sent.put(id,new ArrayList<>());when(p.getUUID()).thenReturn(id);when(p.getId()).thenReturn(online.size()+1);when(p.getScoreboardName()).thenReturn(name);when(p.getTags()).thenAnswer(i->tags.get(id));when(p.getX()).thenAnswer(i->x.get(id));when(p.getZ()).thenReturn(50D);when(p.level()).thenReturn(level);when(level.dimension()).thenReturn(Level.OVERWORLD);when(level.getServer()).thenReturn(server);online.add(p);return p;}
 void tick(){FeatureServer.tick(server);clock.addAndGet(10);}ClientFeatureState client(ServerPlayer p){var c=new ClientFeatureState();sent.get(p.getUUID()).forEach(c::accept);return c;}
 @Test void teachersAndConflictingRolesDoNotDiscoverButReceiveStudentsKnowledge(){var teacher=player("teacher","hj_participant","hj_teacher","hj_student");var outsider=player("outsider");tick();assertTrue(saved.snapshot().ids().isEmpty());assertEquals(0,client(teacher).snapshot().count());x.put(teacher.getUUID(),40D);tick();assertTrue(saved.snapshot().ids().isEmpty());var student=player("student","hj_participant","hj_student");tick();assertEquals(Set.of("sea","river"),saved.snapshot().ids());assertEquals(2,client(teacher).snapshot().count());assertEquals(2,client(student).snapshot().count());assertTrue(sent.get(outsider.getUUID()).isEmpty());verify(teacher,times(1)).sendSystemMessage(any(Component.class));}
 @Test void repeatedMovementHasNoResendOrNotificationAndLateJoinGetsFull(){var p=player("one","hj_participant","hj_student");tick();int before=sent.get(p.getUUID()).size();for(int i=0;i<10;i++){x.put(p.getUUID(),i+40D);tick();}assertEquals(before,sent.get(p.getUUID()).size());verify(p,times(1)).sendSystemMessage(any(Component.class));var second=player("two","hj_participant","hj_student");tick();assertEquals(FeaturePackets.Mode.FULL,sent.get(second.getUUID()).getFirst().mode());assertEquals(client(p).snapshot().features(),client(second).snapshot().features());}
 @Test void acceptedReloadUpdatesLabelsRemovedIdsStayStaleAndRestoredIdsReturn(){var p=player("student","hj_participant","hj_student");tick();var before=saved.snapshot();FeatureCatalog.accept(FeatureModelTest.catalog(FeatureModelTest.polygon("sea",2).replace("Label sea","Changed Sea")));tick();assertEquals(1,client(p).snapshot().count());assertEquals("Changed Sea",client(p).snapshot().features().get("sea").label());assertEquals(before,saved.snapshot());assertTrue(FeatureServer.describe(server).contains("stale=1"));FeatureCatalog.accept(FeatureModelTest.catalog(FeatureModelTest.polygon("sea",2),FeatureModelTest.line("river",1)));tick();assertEquals(2,client(p).snapshot().count());}
 @Test void rejectedReloadDoesNotSendAndResetDoesNotImmediatelyRediscover(){var p=player("student","hj_participant","hj_student");tick();int before=sent.get(p.getUUID()).size();FeatureCatalog.reject("synthetic error");tick();assertEquals(before,sent.get(p.getUUID()).size());saved.reset();FeatureServer.sync(server);tick();assertTrue(saved.snapshot().ids().isEmpty());assertEquals(0,client(p).snapshot().count());x.put(p.getUUID(),51D);tick();assertEquals(2,client(p).snapshot().count());}
 @Test void roleLossRevokesGeometryAndTeacherRejoinGetsSameSharedKnowledge(){var p=player("student","hj_participant","hj_student");tick();tags.get(p.getUUID()).clear();tick();assertEquals(0,client(p).snapshot().count());tags.get(p.getUUID()).addAll(Set.of("hj_participant","hj_teacher"));tick();assertEquals(2,client(p).snapshot().count());}
 @Test void participantResyncIsRateLimitedAndOutsiderCannotRequestKnowledge(){var p=player("student","hj_participant","hj_student");var outsider=player("outsider");tick();int before=sent.get(p.getUUID()).size();FeatureServer.request(p);tick();assertEquals(before+1,sent.get(p.getUUID()).size());FeatureServer.request(p);FeatureServer.request(outsider);tick();assertEquals(before+1,sent.get(p.getUUID()).size());assertTrue(sent.get(outsider.getUUID()).isEmpty());}
 @Test void manySimultaneousDiscoveriesProduceOneBoundedNotification(){var values=new String[20];for(int i=0;i<20;i++)values[i]=FeatureModelTest.polygon("sea_"+i,i);FeatureCatalog.accept(FeatureModelTest.catalog(values));var p=player("student","hj_participant","hj_student");tick();assertEquals(20,saved.snapshot().ids().size());var text=org.mockito.ArgumentCaptor.forClass(Component.class);verify(p,times(1)).sendSystemMessage(text.capture());assertTrue(text.getValue().getString().contains("(+16 more)"));assertTrue(text.getValue().getString().length()<600);}
 @Test void adminCommandsValidatePermissionsIdsAndDoNotNotifyNaturalDiscovery()throws Exception{var teacher=player("teacher","hj_participant","hj_teacher");var dispatcher=new CommandDispatcher<CommandSourceStack>();FeatureCommands.register(new RegisterCommandsEvent(dispatcher,Commands.CommandSelection.ALL,mock(CommandBuildContext.class)));var admin=mock(CommandSourceStack.class);when(admin.hasPermission(2)).thenReturn(true);when(admin.getServer()).thenReturn(server);var student=mock(CommandSourceStack.class);assertFalse(dispatcher.getRoot().getChild("hj").getChild("mapfeature").canUse(student));assertEquals(0,dispatcher.execute("hj mapfeature discovery mark missing",admin));assertTrue(saved.snapshot().ids().isEmpty());assertEquals(1,dispatcher.execute("hj mapfeature discovery mark sea",admin));assertEquals(1,client(teacher).snapshot().count());verify(teacher,never()).sendSystemMessage(any(Component.class));assertEquals(1,dispatcher.execute("hj mapfeature discovery reset",admin));assertEquals(0,client(teacher).snapshot().count());}
}
